ALTER TABLE public.sales ADD COLUMN payment_split jsonb;
CREATE OR REPLACE FUNCTION public.capture_sale_split() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE p jsonb;s jsonb;x jsonb;tot numeric:=0;BEGIN IF NEW.payment_method<>'Mixed' THEN NEW.payment_split:=NULL;RETURN NEW;END IF;p:=nullif(current_setting('app.cheque_payment',true),'')::jsonb;s:=p->'split';IF s IS NULL THEN RETURN NEW;END IF;IF jsonb_typeof(s)<>'array' OR jsonb_array_length(s)<>2 OR s->0->>'method'=s->1->>'method' THEN RAISE EXCEPTION 'Split payment needs two different methods';END IF;FOR x IN SELECT * FROM jsonb_array_elements(s) LOOP IF x->>'method' NOT IN('Cash','Card','Bank Transfer','Cheque') OR (x->>'amount')::numeric<=0 THEN RAISE EXCEPTION 'Invalid split payment part';END IF;tot:=tot+round((x->>'amount')::numeric,2);END LOOP;IF tot<>NEW.paid_now THEN RAISE EXCEPTION 'Split amounts must add up to the amount paid';END IF;NEW.payment_split:=jsonb_build_array(jsonb_build_object('method',s->0->>'method','amount',round((s->0->>'amount')::numeric,2)),jsonb_build_object('method',s->1->>'method','amount',round((s->1->>'amount')::numeric,2)));RETURN NEW;END$$;
CREATE TRIGGER capture_sale_split BEFORE INSERT ON public.sales FOR EACH ROW EXECUTE FUNCTION public.capture_sale_split();
CREATE OR REPLACE FUNCTION public.capture_cheque_payment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE p jsonb;method text;a numeric;BEGIN IF TG_TABLE_NAME='sales' THEN method:=NEW.payment_method;a:=NEW.paid_now;IF method='Mixed' AND NEW.payment_split IS NOT NULL THEN SELECT 'Cheque',(x->>'amount')::numeric INTO method,a FROM jsonb_array_elements(NEW.payment_split) x WHERE x->>'method'='Cheque';IF NOT FOUND THEN RETURN NEW;END IF;END IF;ELSE method:=NEW.method;a:=NEW.amount;END IF;IF method<>'Cheque' OR a<=0 THEN RETURN NEW;END IF;p:=nullif(current_setting('app.cheque_payment',true),'')::jsonb;IF nullif(trim(p->>'cheque_number'),'') IS NULL OR p->>'cheque_date' IS NULL THEN RAISE EXCEPTION 'Cheque number and deposit date are required';END IF;INSERT INTO public.cheque_reminders(branch_id,sale_id,payment_id,cheque_number,cheque_date,amount,created_by) VALUES(NEW.branch_id,CASE WHEN TG_TABLE_NAME='sales' THEN NEW.id ELSE NULL END,CASE WHEN TG_TABLE_NAME='loan_payments' THEN NEW.id ELSE NULL END,trim(p->>'cheque_number'),(p->>'cheque_date')::date,a,auth.uid());RETURN NEW;END$$;